package local.zfttests;
import android.app.*;import android.content.*;import android.os.Bundle;import android.view.*;import android.webkit.WebView;import android.widget.*;import java.lang.reflect.*;import org.json.*;
public class AiNews extends Instrumentation {
 private Activity activity;private Class<?> cls;
 public void onCreate(Bundle b){super.onCreate(b);start();}
 private void require(boolean ok,String why){if(!ok)throw new AssertionError(why);}
 private Object field(String name)throws Exception{Field f=cls.getDeclaredField(name);f.setAccessible(true);return f.get(activity);}
 private void invoke(String name,Class<?>[] types,Object... args)throws Exception{Method m=cls.getDeclaredMethod(name,types);m.setAccessible(true);m.invoke(activity,args);}
 private void ready()throws Exception{long end=System.currentTimeMillis()+40000;while(System.currentTimeMillis()<end){boolean[] busy={true};runOnMainSync(()->{try{busy[0]=(Boolean)field("loading");}catch(Exception e){throw new RuntimeException(e);}});if(!busy[0])return;Thread.sleep(200);}throw new AssertionError("feed timed out");}
 private boolean containsWeb(View view){if(view instanceof WebView)return true;if(view instanceof ViewGroup){ViewGroup g=(ViewGroup)view;for(int i=0;i<g.getChildCount();i++)if(containsWeb(g.getChildAt(i)))return true;}return false;}
 private String allText(View view){if(view instanceof TextView)return ((TextView)view).getText().toString();StringBuilder s=new StringBuilder();if(view instanceof ViewGroup){ViewGroup g=(ViewGroup)view;for(int i=0;i<g.getChildCount();i++)s.append(allText(g.getChildAt(i)));}return s.toString();}
 private void capture(String name)throws Exception{waitForIdleSync();Thread.sleep(600);android.graphics.Bitmap b=getUiAutomation().takeScreenshot();try(java.io.FileOutputStream f=new java.io.FileOutputStream(new java.io.File(getTargetContext().getExternalFilesDir(null),name))){b.compress(android.graphics.Bitmap.CompressFormat.PNG,100,f);}b.recycle();}
 public void onStart(){Bundle out=new Bundle();try{
  cls=getTargetContext().getClassLoader().loadClass("local.zft.AiActivity");Method url=cls.getDeclaredMethod("articleUrl",JSONObject.class);url.setAccessible(true);
  require("".equals(url.invoke(null,new JSONObject("{\"links\":{\"aihot\":\"javascript:alert(1)\"}}"))),"script URL rejected");require("".equals(url.invoke(null,new JSONObject("{\"links\":{\"aihot\":\"https://aihot.news.evil.test/x\"}}"))),"lookalike host rejected");require("https://aihot.news/story/a".equals(url.invoke(null,new JSONObject("{\"links\":{\"story\":\"https://aihot.virxact.com/story/a\"}}"))),"legacy story migrated");
  activity=startActivitySync(new Intent().setClassName(getTargetContext(),"local.zft.AiActivity").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));ready();
  runOnMainSync(()->{try{require(((java.util.Set<?>)field("ids")).size()>0,"live hot feed");require(activity.getWindow().getDecorView().findViewWithTag("local.zft.tab.4").isSelected(),"AI bottom tab selected");((LinearLayout)field("rows")).getChildAt(0).performClick();require(field("reader")!=null,"native reader opens");require(!containsWeb((View)field("reader")),"article contains no embedded website");}catch(Exception e){throw new RuntimeException(e);}});
  long deadline=System.currentTimeMillis()+30000;while(System.currentTimeMillis()<deadline){boolean[] busy={true};runOnMainSync(()->{try{busy[0]=(Boolean)field("readerLoading");}catch(Exception e){throw new RuntimeException(e);}});if(!busy[0])break;Thread.sleep(200);}runOnMainSync(()->{try{String content=allText((View)field("reader"));require(content.contains("事件综述")&&!content.contains("报道摘要")&&!content.contains("查看原文")&&content.length()>300,"live story overview and reports rendered natively");}catch(Exception e){throw new RuntimeException(e);}});capture("ai-reading-preview.png");sendKeyDownUpSync(KeyEvent.KEYCODE_BACK);Thread.sleep(700);runOnMainSync(()->{try{require(field("reader")==null&&!activity.isFinishing(),"system back closes reader, keeps feed");activity.getWindow().getDecorView().findViewWithTag("ai.mode.1").performClick();}catch(Exception e){throw new RuntimeException(e);}});ready();
  capture("ai-selected-preview.png");runOnMainSync(()->{try{((LinearLayout)field("rows")).getChildAt(0).performClick();require(!containsWeb((View)field("reader")),"selected native reader");}catch(Exception e){throw new RuntimeException(e);}});sendKeyDownUpSync(KeyEvent.KEYCODE_BACK);waitForIdleSync();int[] first={0};runOnMainSync(()->{try{first[0]=((java.util.Set<?>)field("ids")).size();require(first[0]>0,"live selected feed");require(!((String)field("cursor")).isEmpty(),"selected cursor available");require(((TextView)field("more")).getVisibility()==View.GONE,"no fixed load-more control");((ScrollView)field("scroll")).scrollTo(0,((LinearLayout)field("rows")).getHeight());}catch(Exception e){throw new RuntimeException(e);}});ready();
  runOnMainSync(()->{try{require(((java.util.Set<?>)field("ids")).size()>first[0],"scroll automatically appends distinct articles");invoke("failed",new Class[]{boolean.class,String.class},true,"测试断网");invoke("finishLoad",new Class[]{});TextView retry=(TextView)field("more");require(retry.getVisibility()==View.VISIBLE&&retry.isEnabled(),"failure offers inline retry");require(retry.getParent()!=field("feed"),"retry stays inside scrolling content");int before=(Integer)field("generation");((ScrollView)field("scroll")).scrollTo(0,((LinearLayout)field("rows")).getHeight());require((Integer)field("generation")==before,"failed pagination cannot loop on scrolling");JSONObject fixture=new JSONObject("{\"items\":[{\"id\":\"a\",\"title\":\"test\",\"links\":{\"aihot\":\"https://aihot.news/items/a\"}},{\"id\":\"a\",\"title\":\"duplicate\",\"links\":{\"aihot\":\"https://aihot.news/items/a\"}},{\"id\":\"bad\",\"title\":\"bad\",\"links\":{\"aihot\":\"https://evil.test\"}}]}");fixture.getJSONArray("items").put(new JSONObject("{\"id\":\"same-title\",\"title\":\"test\",\"links\":{\"aihot\":\"https://aihot.news/items/b\"}}"));invoke("render",new Class[]{JSONObject.class,boolean.class},fixture,false);require(((java.util.Set<?>)field("ids")).size()==1,"dedupe and reject bad links");activity.getWindow().getDecorView().findViewWithTag("ai.mode.0").performClick();require(!(Boolean)field("loading"),"fresh hot cache avoids extra fetch");}catch(Exception e){throw new RuntimeException(e);}});
  Thread.sleep(700);android.graphics.Bitmap b=getUiAutomation().takeScreenshot();try(java.io.FileOutputStream f=new java.io.FileOutputStream(new java.io.File(getTargetContext().getExternalFilesDir(null),"ai-news-preview.png"))){b.compress(android.graphics.Bitmap.CompressFormat.PNG,100,f);}b.recycle();
  ActivityMonitor monitor=addMonitor("local.zft.StockActivity",null,false);runOnMainSync(()->activity.getWindow().getDecorView().findViewWithTag("local.zft.tab.3").performClick());require(waitForMonitorWithTimeout(monitor,5000)!=null,"AI to stocks navigation");removeMonitor(monitor);
  out.putString("result","PASS: live hot/selected/automatic scroll pagination, inline retry guard; cache; URL validation/dedupe; compact native overview/summary without duplicate reports, reasons or external links and system back; five-tab navigation");finish(-1,out);
 }catch(Throwable e){out.putString("result","FAIL: "+e);finish(0,out);}}
}
